import { ref } from 'vue';

export const defaultFilterRow = () => ({
    filter: '',
    key: '',
    operator: 'LIKE',
    value: '',
});

export const filterRelationOptions = [
    { value: 'and', label: 'AND', icon: '' },
    { value: 'or', label: 'OR', icon: '' },
];

export function useFilterConditions(initialFilters = null) {
    const filters = ref(initialFilters || [defaultFilterRow()]);

    const addFilter = () => {
        filters.value = [...filters.value, defaultFilterRow()];
    };

    const removeFilter = (e, id) => {
        filters.value = filters.value.filter((_, i) => i !== id);
    };

    const resetFilters = () => {
        filters.value = [defaultFilterRow()];
    };

    return { filters, addFilter, removeFilter, resetFilters };
}
